#!/usr/bin/env python3
"""Recreate fixtures/ byte-for-byte.

Contents are stored base64-encoded and written in BINARY mode on purpose: the
fixtures include non-UTF-8 binary files and deliberate byte-level tamper cases,
and a text-mode round trip would silently rewrite them and invalidate the
committed sample report hashes. Do not "simplify" this to text mode.

Regenerating the fixtures and re-running the tool reproduces the committed
sample reports byte-for-byte; captured_output.txt shows that round trip.

    python3 make_fixtures.py
"""
import base64
import os
import sys

FILES = {
 "fixtures/clean_bundle/data/records.csv": "aWQsYW1vdW50LG5vdGUKMSwxMDAuMDAsaW5pdGlhbCBkZXBvc2l0CjIsLTI1LjUwLGZlZQozLDUwMC4wMCx0cmFuc2ZlciBpbgo=",
 "fixtures/clean_bundle/manifest.json": "",
 "fixtures/clean_bundle/photos/exhibit_a.bin": "",
 "fixtures/clean_bundle/photos/\u73fb\u5217e_b.bin": "",
 "fixtures/clean_bundle/readme.txt": "RXZpZGVuY2UgYnVuZGxlIGZvciBjYXNlIDIwMjYtMDE0Mi4gU2VlIGRhdGEvcmVjb3Jkcy5jc3YgZm9yIHRoZSBleHBvcnRlZCBsZWRnZXIuCg==",
 "fixtures/tampered_bundle/ledger.csv": "bGVkZ2VyLGJhbGFuY2UKMSwxMDAKMiwyMDAK",
 "fixtures/tampered_bundle/manifest.json": "",
 "fixtures/tampered_bundle/photo.bin": "",
 "fixtures/tampered_bundle/statement.txt": "T1JJR0lOQUwgd2l0bmVzcyBzdGF0ZW1lbnQsIFVOTU9ESUZJRUQgYm9keSB0ZXh0IGhlcmUuLi4uLi4u",
 "fixtures/tampered_bundle/unlisted_backup_copy.txt": "dGhpcyBmaWxlIHdhcyBhZGRlZCBhZnRlciB0aGUgbWFuaWZlc3Qgd2FzIHByb2R1Y2Vk"
}


def main():
    dest = sys.argv[1] if len(sys.argv) > 1 else "."
    for rel in sorted(FILES):
        path = os.path.join(dest, *rel.split("/"))
        parent = os.path.dirname(path)
        if parent:
            os.makedirs(parent, exist_ok=True)
        with open(path, "wb") as fh:
            fh.write(base64.b64decode(FILES[rel]))
    print("wrote %d files to %s" % (len(FILES), dest))
    return 0


if __name__ == "__main__":
    sys.exit(main())
